import sys
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def imgMultiply(root):
    MOD = 10**9 + 7
    def dfs(node1, node2):
        if not node1 or not node2:
            return 0
        return ((node1.val * node2.val) + dfs(node1.left, node2.right) + dfs(node1.right, node2.left)) % MOD
    return dfs(root, root)

def read_input():
    import sys
    input = sys.stdin.read().split()
    nodes = list(map(int, input))
    from collections import deque
    dq = deque(nodes)
    root = TreeNode(dq.popleft())
    q = deque([root])
    while dq:
        current = q.popleft()
        left_val = dq.popleft() if dq else None
        right_val = dq.popleft() if dq else None
        if left_val is not None:
            current.left = TreeNode(left_val)
            q.append(current.left)
        if right_val is not None:
            current.right = TreeNode(right_val)
            q.append(current.right)
    return root

if __name__ == "__main__":
    root = read_input()
    result = imgMultiply(root)
    print(result)
